package cn.workbench;
import org.springframework.stereotype.Component;import org.springframework.boot.ApplicationRunner;import org.springframework.boot.ApplicationArguments;import org.springframework.core.env.Environment;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;import java.util.*;
@Component public class Bootstrap implements ApplicationRunner {
 final Store db;final Records records;final PasswordEncoder passwords;final Environment env;final String password;final TransactionTemplate tx;
 public Bootstrap(Store d,Records r,PasswordEncoder p,Environment e,@Value("${task.bootstrap-password:}")String pw,PlatformTransactionManager m){db=d;records=r;passwords=p;env=e;password=pw;tx=new TransactionTemplate(m);}
 @Override public void run(ApplicationArguments a){boolean demo=Arrays.stream(env.getActiveProfiles()).anyMatch(x->x.equals("demo")||x.equals("test")||x.equals("bootstrap"));boolean provision=Arrays.asList(env.getActiveProfiles()).contains("provision");if(!demo){for(String name:List.of("TASK_DB_URL","TASK_DB_USER","TASK_DB_PASSWORD","TASK_TOTP_ENCRYPTION_KEY"))if(env.getProperty(name,"").isBlank())throw new IllegalStateException("Required production environment: "+name);if(!provision)return;}if(!db.users().isEmpty())return;if(password.length()<12)throw new IllegalStateException("Empty demo requires TASK_BOOTSTRAP_PASSWORD of at least12 characters");if(provision){tx.execute(status->{var company=records.create("COMPANY",0,null,null,null,"ACTIVE",Records.map("name",env.getProperty("TASK_BOOTSTRAP_COMPANY_NAME","初始公司"),"enabled",true,"companyCode",env.getProperty("TASK_BOOTSTRAP_COMPANY_CODE","INIT")));int companyId=Jsons.integer(company.get("id"));createUser(env.getProperty("TASK_BOOTSTRAP_ACCOUNT","bootstrap.admin"),"初始管理员","ADMIN",companyId,null);records.create("KPI_TEMPLATE",0,null,null,null,"APPROVED",Records.map("name","V1.4兼容模板","templateVersion",1,"approved",true,"weightsJson","[30,25,20,10,15]","personalEnabled",false,"baseline",List.of(70,20,15,8,24),"targets",List.of(90,5,5,2,12)));return null;});return;}tx.execute(status->{var c1=records.create("COMPANY",0,null,null,null,"ACTIVE",Records.map("name","示范集团子公司甲","enabled",true,"companyCode","DEMOA"));int company1=Jsons.integer(c1.get("id"));var c2=records.create("COMPANY",0,null,null,null,"ACTIVE",Records.map("name","示范集团子公司乙","enabled",true,"companyCode","DEMOB"));int company2=Jsons.integer(c2.get("id"));var d1=records.create("DEPARTMENT",company1,null,null,null,"ACTIVE",Records.map("name","综合管理部","enabled",true));int dept1=Jsons.integer(d1.get("id"));var d2=records.create("DEPARTMENT",company1,null,null,null,"ACTIVE",Records.map("name","财务部","enabled",true));int dept2=Jsons.integer(d2.get("id"));var d3=records.create("DEPARTMENT",company2,null,null,null,"ACTIVE",Records.map("name","运营部","enabled",true));int dept3=Jsons.integer(d3.get("id"));createUser("demo.admin","演示管理员","ADMIN",company1,null);createUser("demo.leader","演示公司领导","COMPANY_LEADER",company1,null);createUser("demo.head","演示部门主管","DEPT_HEAD",company1,dept1);createUser("demo.employee","演示员工","EMPLOYEE",company1,dept1);createUser("demo.finance","演示财务主管","DEPT_HEAD",company1,dept2);createUser("demo.other","演示乙公司主管","DEPT_HEAD",company2,dept3);createUser("demo.group","演示集团领导","GROUP_LEADER",null,null);records.create("TAG",company1,dept2,null,null,"ACTIVE",Records.map("name","财务","weight",100));records.create("TAG",company1,dept1,null,null,"ACTIVE",Records.map("name","综合","weight",80));records.create("KPI_TEMPLATE",0,null,null,null,"APPROVED",Records.map("name","V1.4兼容模板","templateVersion",1,"approved",true,"weightsJson","[30,25,20,10,15]","personalEnabled",false,"baseline",List.of(70,20,15,8,24),"targets",List.of(90,5,5,2,12)));return null;});}
 void createUser(String account,String name,String role,Integer company,Integer dept){Map<String,Object> u=Records.map("account",account,"name",name,"passwordHash",passwords.encode(password),"mustChangePassword",true);db.insertUser(u);db.insertScope(Records.map("userId",u.get("id"),"role",role,"companyId",company,"deptId",dept));}
}
